/**
 * Fail when `npm run codegen` leaves any codegen-owned path dirty.
 *
 * Replaces `git diff --exit-code -- generated`, which only compared tracked
 * files inside `generated/`. `generate-pydantic.sh` also rewrites
 * `tests/test_generated_models.py` (its TEST_FIXTURE), so a stale committed
 * fixture regenerated by codegen produced no visible diff and the check passed.
 * Untracked new emissions were invisible for the same reason — `git diff`
 * ignores them entirely.
 *
 * `git status --porcelain` covers staged, unstaged, and untracked changes for
 * the given paths only, so an unrelated dirty file in the working tree does not
 * fail the check.
 */

import { execFileSync } from "node:child_process";

/** Every path codegen writes: see generate-pydantic.sh (OUT_DIR, TEST_FIXTURE). */
const CODEGEN_OWNED_PATHS = ["generated", "tests/test_generated_models.py"];

const status = execFileSync(
  "git",
  ["status", "--porcelain", "--untracked-files=all", "--", ...CODEGEN_OWNED_PATHS],
  { encoding: "utf8" },
).trim();

if (status) {
  console.error(
    "codegen:check FAILED - regenerating the schemas changed files that are committed:",
  );
  console.error(status);
  console.error(
    "\nRun `npm run codegen` and commit the result, so the committed artifacts match the emitters.",
  );
  process.exit(1);
}

console.log(
  `codegen:check passed - ${CODEGEN_OWNED_PATHS.join(", ")} match the committed artifacts.`,
);